  LanguageConfig_2ndAnniversaryText_CN = {
    Text = "তুমি যেখানে-ই থাকো না কেন, %player%।\nমিথাগ একটি মাত্রাগত সংযোগ স্থাপনের চেষ্টা করে চলেছে, হয়তো খুব শিগগিরই আমরা আবারও একে অপরের মুখোমুখি হবো।\nডল বলেছে, সে নাকি নির্ভুলভাবে নির্ণয় করে ফেলেছে তুমি কোন মাত্রায় আছো, আর সেই সংবাদ আমার হৃদয়ে যে আনন্দ ঢেলে দিয়েছে, তা ভাষায় বর্ণনা করা যায় না।\nযদিও আমি স্বভাবতই স্বচ্ছ, নির্ভুল, সুস্পষ্ট বিষয় পছন্দ করি, তবু এই প্রসঙ্গে যেকোনো অস্পষ্ট, এমনকি অবাস্তব আশাও সাদরে গ্রহণযোগ্য।\nআমি এমন এক বিচ্ছেদের কথা কল্পনাও করতে পারি না, যার দীর্ঘ প্রতীক্ষার শেষে কোনো পুনর্মিলন নেই।\nএইবার যদি না-ও হয়, তাতে কিছু আসে যায় না; পরের বার, তারও পরের বার, কিংবা হাজারবার—যতবারই লাগুক না কেন, মিথাগের আমরা সবাই মিলে অবশ্যই তোমাকে ফিরিয়ে আনবো।\nআমরা এখন দুই ভিন্ন মাত্রায় অবস্থান করলেও, মিথাগ এখনও সিলভার টেকনোলজির সাহায্যে কিছু সম্ভাবনা একত্র করার পথ খুঁজে চলেছে, যাতে তোমাকে সহায়তা করা যায়। অনুগ্রহ করে আমাদের অতীত স্মৃতিগুলো সংগ্রহ করো, নতুন স্মৃতি গড়ে তোলো, আর এই উপহারগুলোকে তোমার সহায় হতে দাও।\nআমরা সবাই জানি, তুমি অবশ্যই ফিরে আসবে।\nকারণ অপেক্ষা করতে আমি খুবই পারদর্শী।"
