  LanguageConfig_AlchemyDecomposeWeaponRuleContent_CN = {
    Text = "1. কিপাররা এখানে নিয়তিচক্রের বিযোজন সম্পন্ন করতে পারেন। একবার বিযোজিত হলে তা আর পুনরুদ্ধার করা যায় না, তাই কিপারদের উচিত সতর্কতার সঙ্গে নির্বাচন করা। \n2. যদি বিযোজনের জন্য নির্বাচিত নিয়তিচক্রের মধ্যে কোনো SSR‑স্তরের চক্র বা ইতোমধ্যে আরোহিত কোনো চক্র থাকে, তবে সেটি বিযোজনের আগে কিপারকে একটি কুইজ সম্পন্ন করতে হবে। \n3. সীমাবদ্ধতা‑বিহীন SSR‑স্তরের নিয়তিচক্র বিযোজন করলে 1টি 「নিয়তি প্রত্যাবর্তন খণ্ড」 এবং 2000 「রোজ স্ক্রিপ」 পাওয়া যাবে। যদি সীমিত SSR‑স্তরের নিয়তিচক্র বিযোজন করা হয়, তবে প্রাপ্ত 「নিয়তি প্রত্যাবর্তন খণ্ড」-এর পরিমাণ দ্বিগুণ হবে। \n4. যে সব চক্র বর্তমানে কোনো 「লাইনআপ」 বা 「সহায়ক জাগরণকারী」-তে ব্যবহৃত হচ্ছে, সেগুলো বিযোজন করা যাবে না।"
