  LanguageConfig_AssistanceSystemIntroduction_CN = {
    Text = "1 জন জাগরণকারীকে সাপোর্ট হিসেবে সেট করো। পারস্পরিকভাবে ফলো করা রক্ষকেরা তোমার সাপোর্ট জাগরণকারীকে ডিজলিউশন ধ্বংসাবশেষ, ফেয়ারবোটেন চুক্তিপত্র, এবং মায়াবী অবগাহন-এ ব্যবহার করতে পারবে।\nঅন্য কোনো রক্ষক তোমার সাপোর্ট জাগরণকারী ব্যবহার করে প্রতিবার সফল তদন্ত সম্পন্ন করলে তুমি পাবে রোজ স্ক্রিপ ×1000, দৈনিক সর্বোচ্চ 20 বার পর্যন্ত।\nসাপোর্ট জাগরণকারী পুরস্কার 50 বার পাওয়ার পর, আরও পুরস্কার পেতে হলে তোমাকে আগে সেগুলো গ্রহণ করতে হবে।"
