  LanguageConfig_AwakerAssistRule_CN = {
    Text = "ডিজলিউশন ধ্বংসাবশেষ, ফেয়ারবোটেন চুক্তিপত্র, মায়াবী অবগাহন এবং রহস্যময় আধিপত্য ইত্যাদি গেমপ্লেতে অংশ নেওয়ার সময়, তুমি পারস্পরিকভাবে ফলো করা কোনো রক্ষকের 1 জন সাপোর্ট অ্যাওয়েকনারকে কমব্যাট অ্যাসিস্ট ইউনিট হিসেবে বেছে নিতে পারো।\nসহায়ক অ্যাওয়েকনারকে বর্তমান লাইনআপের রিয়ালম সীমাবদ্ধতা পূরণ করতে হবে; শর্ত পূরণ না করলে সেই সহায়ক অ্যাওয়েকনার ময়দানে নামতে পারবে না। অংশগ্রহণের আগে রক্ষকরা ফিরে গিয়ে লাইনআপ সমন্বয় করতে পারেন।\nকিছু ইভেন্টে অতিরিক্ত বিশেষ কমব্যাট অ্যাসিস্ট নিয়ম থাকতে পারে। বিস্তারিত জানতে অনুগ্রহ করে সেই ইভেন্টের 「অ্যাক্টিভিটি ডেসক্রিপশন」 দেখো।"
