  LanguageConfig_AwakerFavorability_Description_Detail_CN = {
    Text = "<Title:[সমসংস্থান হার অর্জন】>\n·অভিযান, বিশেষ অভিযান রেকর্ড, চেতনার বিচরণ এবং মায়াবী অবগাহন প্রভৃতি স্তর ক্লিয়ার করার পর, দলে থাকা জাগরণকারী সমসংস্থান হার অর্জন করতে পারে।\n·জাগরণকারী যত বেশি কার্ড খেলবে, যত বেশি অ্যারিথমেটিকা ও অ্যালিমাস ব্যয় করবে, তত বেশি সমসংস্থান হার অর্জিত হবে; স্তরের প্রস্তাবিত মাত্রা যত বেশি, সমসংস্থান হারও তত বেশি।\n·রক্ষকের S-শক্তি যত বেশি ব্যয় হবে, দলে থাকা জাগরণকারীর সমসংস্থান হারও তত বেশি হবে।\n·ম্যানুয়াল যুদ্ধের সময় অর্জিত সমসংস্থান হার 「স্বয়ংক্রিয় যুদ্ধ」 চালু থাকার তুলনায় ৩ গুণ।\n·সহায়তা যুদ্ধ ব্যবহার করে স্তর ক্লিয়ার করলে, রক্ষকের দলে থাকা জাগরণকারীর সমসংস্থান হার অর্জন ৫০% বৃদ্ধি পায়।\n·জাগরণকারীকে ডর্মিটরিতে আমন্ত্রণ জানানোর পর, প্রতি ৫ মিনিটে ১ পয়েন্ট সমসংস্থান হার অর্জন করা যায়।\n·অফলাইনে ৩০০ পয়েন্টের বেশি সঞ্চিত হলে, অর্জনের গতি প্রতি ১৫ মিনিটে ১ পয়েন্টে নেমে আসে, সর্বোচ্চ ৩০০০ পয়েন্ট পর্যন্ত সঞ্চয় করা যায়।\n\n<Title:[সমসংস্থান হার স্তর】>\n·জাগরণকারীর সমসংস্থান হার সংগ্রহ করলে সমসংস্থান হার স্তর বৃদ্ধি পায়, স্তর যত বেশি হবে তত বেশি জাগরণকারীর ভয়েস ও গল্প আনলক করা যাবে, এবং কিছু স্তরে 「নির্মল মর্ম」 পাওয়া যাবে।\n·জাগরণকারীর সমসংস্থান হার Lv15 পৌঁছানোর পর, 「আত্মা-দেহ সমন্বয়」-এর মাধ্যমে 「একতার প্রমাণ」 ব্যয় করে স্তরের সীমা ধাপে ধাপে Lv20 পর্যন্ত বাড়ানো যাবে, প্রতিটি স্তরে 「পরিশোধিত আত্মিক মূল খণ্ড」×৫ পাওয়া যাবে, এবং Lv20-তে পৌঁছালে অতিরিক্তভাবে 「দীপ্তিময় ঝলক」 পাওয়া যাবে।\n·জাগরণকারীর সমসংস্থান হার বর্তমান স্তরের সীমায় পৌঁছানোর পর আর জমা হবে না, চালিয়ে যেতে হলে আগে আত্মা-দেহ সমন্বয় সম্পন্ন করতে হবে।"
