  LanguageConfig_BPNewOpenContent_CN = {
    Text = "নতুন সেমিস্টারের কোর্স উন্মুক্ত হয়েছে!\nগোপন কক্ষের দৈনিক ট্রায়াল ও সাপ্তাহিক ট্রায়াল সম্পন্ন করুন, কোর্সের লেভেল বাড়ান এবং দুর্দান্ত পুরস্কার পান!"
