  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "তুমি যে প্রতিটি ফোঁটা সিলভার প্রাইম দান করো, তা অমূল্য। তা ব্যবহৃত হবে ডিজলিউশন গবেষণা ও ক্যাম্পাস নির্মাণে, আমাদের বিস্মৃতির বিরুদ্ধে সংগ্রামে অবদান রাখবে।\nরৌপ্য চাবি আমাদের পথ দেখাক।"
