  LanguageConfig_EnergyMonthCardRuleContent_CN = {
    Text = "[In-Sheath Supply Introduction]\nপ্রতিবার তুমি খাপের মধ্যে সরবরাহ কিনলে, সঙ্গে সঙ্গে পাবে 680 সিলভার এবং 30 দিনের খাপের মধ্যে সরবরাহের মেয়াদ।\nখাপের মধ্যে সরবরাহের মেয়াদ চলাকালীন, তুমি প্রতিদিন মেইল থেকে 300 মেনোফিন এবং 30টি স্মৃতিচারণ পালকের কলম পাবে, যা সকাল 9:00 টায় [GMT+8] রিসেট হবে।\n\n[Notes]\nমোট খাপের মধ্যে সরবরাহের মেয়াদ কেবল তখনই বাড়ানো হবে, যখন অবশিষ্ট মেয়াদ ≤180 দিন থাকা অবস্থায় তুমি পুনরায় ক্রয় করবে।\nঅবশিষ্ট খাপের মধ্যে সরবরাহের মেয়াদ >180 দিন থাকলে তুমি আবার ক্রয় করতে পারবে না।\nবিশেষ কারণে যদি পুনরায় ক্রয় হয়ে যায়, তবে মোট মেয়াদ আর যোগ হবে না, এবং 680 সিলভার সরাসরি ফেরত দেওয়া হবে।\nখাপের মধ্যে সরবরাহের মেয়াদ চলাকালীন যে মেনোফিন এবং স্মৃতিচারণ পালকের কলম সংগ্রহ করা হয়নি, সেগুলো ফেরত দেওয়া হবে না।"
