  LanguageConfig_PasswordBattleRuleTips_CN = {
    Text = "পাসওয়ার্ড ব্যাটল: একটি ব্যাটল তৈরি করার পর, আপনি <color=#5EF2FF>পাসওয়ার্ড</color> শেয়ার করে সামাজিক মাধ্যম বা মেসেজিং সফটওয়্যারের মাধ্যমে অন্যদের আমন্ত্রণ জানাতে পারবেন।\nঅন্যান্য কিপাররা একই <color=#5EF2FF>পাসওয়ার্ড</color> প্রবেশ করিয়ে আপনার ব্যাটলে যোগ দিতে পারবেন।\nআপনি এক সময়ে কেবল একজনের সাথে ব্যাটল শুরু করতে পারেন বলে, আসন পূরণ হবে আগে আসলে আগে পাবেন ভিত্তিতে। ব্যাটল সফলভাবে শুরু হয়ে গেলে, অন্য সব আমন্ত্রিত কিপার স্বয়ংক্রিয়ভাবে প্রত্যাখ্যাত হবে।\n\nব্যাটল প্রত্যাখ্যান: যদি এমন কোনো কিপারের মুখোমুখি হন যার সাথে আপনি লড়তে চান না, তবে আপনি ম্যাচটি প্রত্যাখ্যান করতে পারবেন।\nঅতিরিক্ত সংখ্যক ব্যাটল প্রত্যাখ্যান করলে একটি ব্লক সতর্কতা সক্রিয় হবে, যা ব্লক উঠে যাওয়া পর্যন্ত ঐ কিপারকে আপনার ভবিষ্যতের ব্যাটলে যোগ দিতে বাধা দেবে।"
