  LanguageConfig_PermanentActivityRuleContent_CN = {
    Text = "<Title:স্মৃতি গ্যালারি>\n·「স্মৃতি গ্যালারি」চিহ্নযুক্ত ইভেন্টগুলো, ইভেন্টের সময়সীমা শেষ হওয়ার পর「স্মৃতি গ্যালারি」-তে সংরক্ষিত হবে, যেখানে আপনি সংশ্লিষ্ট গেমপ্লে এবং গল্প উপভোগ করতে পারবেন।\n<Title:সংরক্ষণের নিয়ম>\n·「স্মৃতি গ্যালারি」চিহ্নযুক্ত ইভেন্টগুলোতে প্রচুর সময়-সীমিত পুরস্কার থাকবে। ইভেন্টের সময়সীমা শেষ হওয়ার পর সময়-সীমিত পুরস্কারগুলো আর সংগ্রহ করা যাবে না, তাই সকল রহস্যরক্ষককে সময়মতো সময়-সীমিত পুরস্কার সংগ্রহ করার অনুরোধ করা হচ্ছে।\n·ইভেন্ট「স্মৃতি গ্যালারি」-তে সংরক্ষিত হওয়ার পর, পূর্বের অগ্রগতি স্বয়ংক্রিয়ভাবে সংরক্ষিত থাকবে এবং সকল রহস্যরক্ষক অভিজ্ঞতা উপভোগ করা চালিয়ে যেতে পারবেন।"
