  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "「হেকটিক স্কাইবাউন্ড রেল」-এ একটি লেভেল ক্ষতিপূরণ ব্যবস্থা রয়েছে, যার নিয়মাবলি নিম্নরূপ:\nতদন্ত দলে থাকা যেসব অ্যাওয়েকেনারের লেভেল 60-এর নিচে, এই চ্যালেঞ্জের জন্য তাদের লেভেল 60-এ ক্ষতিপূরণ করা হবে।\nতদন্ত দলে থাকা যেসব অ্যাওয়েকেনারের স্কিল লেভেল 5-এর নিচে, এই চ্যালেঞ্জের জন্য তাদের স্কিল লেভেল 5-এ ক্ষতিপূরণ করা হবে।\nতদন্ত দলে থাকা যেসব অ্যাওয়েকেনারের 「উন্মাদনার পূর্বলক্ষণ」 লেভেল 6-এর নিচে, এই চ্যালেঞ্জের জন্য তা লেভেল 6-এ ক্ষতিপূরণ করা হবে।\nতদন্ত দলে থাকা যেসব অ্যাওয়েকেনারের 「সোলফোর্জ যোগ্যতা」 লেভেল 5-এর নিচে, এই চ্যালেঞ্জের জন্য তা লেভেল 5-এ ক্ষতিপূরণ করা হবে।\nযদি কিপারের লেভেল 60-এর নিচে হয়, এই চ্যালেঞ্জের জন্য সেটিও লেভেল 60-এ ক্ষতিপূরণ করা হবে।"
