  LanguageConfig_ReturnEventRewardText_CN = {
    Text = "ডিজলিউশনের বিরুদ্ধে লড়াইয়ের এই মিশনটি অজানার দিকে একমুখী যাত্রা, ফাঁদ আর বিপদে ভরা।\n「পৃথিবীকে রক্ষা করা」—এই উদ্দেশ্যটি অতিরিক্ত বিশাল, আর নিজেকে হারিয়ে ফেলার জন্য অতিরিক্ত সহজ। মিথাগ বিশ্ববিদ্যালয়ের ইতিহাস জুড়ে, অসংখ্য তরুণ অনুসন্ধান কর্মকর্তা তাদের মিশনবোধের মোহে পুড়ে ছাই হয়ে গেছে, যুক্তির সীমা পেরিয়ে।\nতুমি বিশ্রাম নেওয়ার সিদ্ধান্ত নিয়েছ—এতে আমরা সবাই স্বস্তি পেয়েছি। আরেকজন কিপারকে হারানোর সামর্থ্য আমাদের নেই।\nআনুষ্ঠানিক সৌজন্য যথেষ্ট হয়েছে। যত দ্রুত সম্ভব তোমাকে আবার তদন্তে ফিরিয়ে আনতে, আমি তোমার জন্য একটি পুনরারম্ভ প্রশিক্ষণ পরিকল্পনা তৈরি করেছি। ধাপে ধাপে তা সম্পন্ন করো, ফলাফল নিয়ে আমার কাছে এসো, আর আমি তোমাকে পুরস্কৃত করব।\nআরও একটা কথা—রামোনা তোমার জন্য কিছু 「ছোট উপহার」 প্রস্তুত করেছে। সে তোমাকে ভীষণ মিস করেছে।"
