  LanguageConfig_SmallSubplotTipsText_CN = {
    Text = "<Title:Psyche Deepdive>\n১. আনলক করার শর্ত:\nপ্রয়োজনীয় পূর্বশর্ত তদন্ত সম্পন্ন করো;\nআনলক করতে নির্দিষ্ট পরিমাণ 「রিয়ালিটি ভার্জ」 ব্যয় করো।\n২. নির্দিষ্ট কিছু ইভেন্ট চলাকালে, Psyche Deepdive ধাপগুলো বিনামূল্যে আনলক করা যাবে। ইভেন্ট শেষ হওয়ার পরও তোমার তদন্ত অগ্রগতি ধরে রাখা হবে।\n৩. Psyche Deepdive ধাপ ক্লিয়ার করলে নিম্নলিখিত পুরস্কার পাও: নির্মল মর্ম, রক্ষক EXP, এবং অনুসন্ধান ব্যাজ।"
