  LanguageConfig_Task_Appoint_Rules_CN = {
    Text = "<Title:[Assignment Rules]>\nরক্ষকেরা জাগরণকারীদের তদন্ত বা গবেষণা কাজের জন্য নিয়োগ করতে পারেন, এবং সমাপ্তির পর সংশ্লিষ্ট পুরস্কার অর্জন করবেন।\nমোট নিয়োগ স্তর যদি কাজের প্রয়োজনীয়তা পূরণ করে, তবেই প্রেরণ সফল হয়। প্রতিটি কাজে সর্বোচ্চ 4 জন জাগরণকারীকে একসঙ্গে নিয়োগ করা যায়।\nকোনো কাজের প্রয়োজনীয় স্তরের প্রতি 20 স্তর বেশি থাকলে অতিরিক্ত একটি পুরস্কার প্রদান করা হয়।\nপ্রতিটি জাগরণকারী একই সময়ে কেবল একটি কাজেই অংশ নিতে পারে। কোনো কাজ বাতিল করলে জাগরণকারী দ্রুত মুক্ত হয়, কিন্তু সেই কাজের সব পুরস্কার ত্যাগ করতে হয়।\nরক্ষকের স্তর 20/30/40/50/60-এ পৌঁছালে, নিয়োগযোগ্য কাজের সংখ্যা প্রতিবার 1টি করে বৃদ্ধি পায়।\nনোট: জেনেসিস রূপে থাকা জাগরণকারীদের নিয়োগ করা যাবে না।"
