  },
  LanguageConfig_TrinketConversionRule_CN = {
    Text = "<Title:ট্রান্সক্রিপশন>\nট্রান্সক্রিপশন কভেন্যান্টের উপ-গুণাবলির ধরন ও মান পরিবর্তন করতে পারে, তবে মূল গুণাবলির ধরন ও মানের উপর কোনো প্রভাব ফেলে না।\nট্রান্সক্রিপশন চলাকালীন, উপ-গুণাবলির ধরন মূল গুণাবলির সঙ্গে মিলে যেতে পারে, এবং উপ-গুণাবলিগুলোর ধরন পরস্পরের সঙ্গেও মিলে যেতে পারে।\nট্রান্সক্রিপশন চলাকালীন, উপ-গুণাবলিগুলো তাদের মানে ভিন্ন ভিন্ন মাত্রার শক্তি লাভ করবে।\nকভেন্যান্ট ট্রান্সক্রিপশন আনলক করার পর, রক্ষক যে কোনো নতুন কভেন্যান্ট অর্জন করলে তা স্বয়ংক্রিয়ভাবে একবার বিনামূল্যে ট্রান্সক্রাইব হবে।\n\n<Title:লক করা>\nট্রান্সক্রিপশন চলাকালীন, যদি কিছু উপ-গুণাবলি সংরক্ষণ করা প্রয়োজন হয়, তবে উপ-গুণাবলির পাশের লক বোতামে ক্লিক করে সেটিকে লক করতে পারেন; লক করা উপ-গুণাবলির ধরন ও মান ট্রান্সক্রিপশন চলাকালীন অপরিবর্তিত থাকবে।\nএকসাথে সর্বোচ্চ দুইটি উপ-গুণাবলি লক করা যেতে পারে।\nএকটি উপ-গুণাবলি লক করতে অতিরিক্ত 「কভেন্যান্ট অবশিষ্টাংশ」*20 খরচ হবে; দুইটি উপ-গুণাবলি লক করতে অতিরিক্ত 「স্মৃতিচারণ পালকের কলম」*10 খরচ হবে।\nএকটি গুণাবলি লক করার সময়, আপনি 「অবশিষ্টাংশ পূরণে স্মৃতিচারণ পালকের কলম ব্যয় করো」 বিকল্পে টিক দিতে পারেন; টিক দেওয়া থাকলে, বর্তমান 「কভেন্যান্ট অবশিষ্টাংশ」 অপর্যাপ্ত হলে, প্রয়োজনীয় সংখ্যক স্মৃতিচারণ পালকের কলম স্বয়ংক্রিয়ভাবে ব্যয় করে ট্রান্সক্রিপশন সম্পন্ন করা হবে।"
  },
  LanguageConfig_TrinketConversion_CN = {
