  LanguageConfig_TrinketCopyRules_CN = {
    Text = "1. ফেয়ারবোটেন চুক্তিপত্রের পর্যায়সমূহ সম্পন্ন করলে তুমি একটি কভেন্যান্ট পেতে পারো!\n2. ভিন্ন ভিন্ন সুপারিশকৃত লেভেলের পর্যায় ভিন্ন পরিমাণ কভেন্যান্ট প্রদান করে।\n সুপারিশকৃত লেভেল 25‑এর পর্যায় 1টি কভেন্যান্ট দেয়।\n সুপারিশকৃত লেভেল 35‑এর পর্যায় 2টি কভেন্যান্ট দেয়।\n সুপারিশকৃত লেভেল 45‑এর পর্যায় 3টি কভেন্যান্ট দেয়।\n3. পর্যায়ের চ্যালেঞ্জ সম্পন্ন করার পর 「Reenact「 আনলক হবে, যা ব্যবহার করে তুমি সঙ্গে সঙ্গে সেই পর্যায়ের মিশন পুরস্কার গ্রহণ করতে পারবে। প্রতিটি Reenact‑এ একটি তদন্তের সমপরিমাণ মেনোফিন ব্যয় হয়।\n4. তদন্ত ইভেন্টের প্রতিটি অধ্যায় সম্পন্ন করলে একটি কভেন্যান্ট পর্যায় আনলক হয়।\n5. তুমি যদি কোনো উচ্চ‑কঠিনতার পর্যায় তিন‑তারকা রেটিংসহ সম্পন্ন করো, তবে নিম্ন‑কঠিনতার পর্যায়গুলোর অগ্রগতি স্বয়ংক্রিয়ভাবে তিন‑তারকা সম্পন্ন হিসেবে চিহ্নিত হবে।"
